import struct, json

data = open('/app/trunc.db','rb').read()

def read_varint(buf, pos):
    result = 0
    for i in range(9):
        byte = buf[pos]; pos += 1
        if i == 8:
            result = (result << 8) | byte
            break
        result = (result << 7) | (byte & 0x7f)
        if not (byte & 0x80):
            break
    return result, pos

def read_value(buf, pos, st):
    if st == 0:
        return None, pos
    if st == 1:
        v = buf[pos]; pos+=1; return (v-256 if v>=128 else v), pos
    if st == 2:
        v = struct.unpack('>H', buf[pos:pos+2])[0]; pos+=2; return (v-65536 if v>=32768 else v), pos
    if st == 3:
        b = buf[pos:pos+3]; v=0
        for x in b: v=(v<<8)|x
        pos+=3; return (v-2**23 if v>=2**22 else v), pos
    if st == 4:
        v=struct.unpack('>i',buf[pos:pos+4])[0]; pos+=4; return v, pos
    if st == 5:
        b=buf[pos:pos+6]; v=0
        for x in b: v=(v<<8)|x
        pos+=6; return (v-2**47 if v>=2**46 else v), pos
    if st in (6,7,8):
        v=struct.unpack('>q',buf[pos:pos+8])[0]; pos+=8; return v, pos
    if st == 9:
        v=struct.unpack('>d',buf[pos:pos+8])[0]; pos+=8; return v, pos
    if st == 10:
        return 0, pos
    if st == 11:
        return 1, pos
    if st >= 12:
        if st & 1:
            ln=(st-13)//2; v=buf[pos:pos+ln]; pos+=ln; return v, pos
        else:
            ln=(st-12)//2; v=buf[pos:pos+ln]; pos+=ln; return v, pos
    raise Exception('bad st %d'%st)

def parse_record(payload):
    h, p = read_varint(payload, 0)
    serials=[]
    for i in range(h-1):
        st,p = read_varint(payload,p)
        serials.append(st)
    vals=[]
    for st in serials:
        v,p = read_value(payload,p,st)
        vals.append(v)
    return vals, p, serials

